/**
 * The seek icon of [seconds] (5..55, clamped): the same drawable in the app, the mini-player and the
 * media notification, so the buttons look alike everywhere and only their size changes.
 */
@DrawableRes
fun seekIconRes(forward: Boolean, seconds: Int): Int {
    val index = seconds.coerceIn(5, 55) - 5
    return if (forward) seekForwardIcons[index] else seekBackIcons[index]
}
